            return 29;
          else
            return 28;
        default:
          return 31;
      }
    } else {
      return super.getNumSubCells(lv);
    }
  }

private int slowSubCells(LevelledValue lv) {
    int field = FIELD_BY_LEVEL[lv.getLevel()+1];
    if (field == -1 || field == Calendar.YEAR || field >= Calendar.HOUR_OF_DAY)
