  private static byte docValuesByte(DocValuesType type) {
    if (type == null) {
      return 0;
    } else {
      switch(type) {
      case NUMERIC:
        return 1;
      case BINARY:
        return 2;
      case SORTED:
        return 3;
      case SORTED_SET:
        return 4;
      case SORTED_NUMERIC:
