          }
          assert total == len;
        } catch (IOException ioe) {
          throw new IOException(ioe.getMessage() + ": " + this, ioe);
        }
      }
    }

    @Override
    protected void seekInternal(long position) {
    }

    boolean isFDValid() throws IOException {
      return file.getFD().valid();
    }
  }

