      boolean exhausted = false;
      while (charsRead < limit) {
        final int inc = input.read(chars, charsRead, chars.length-charsRead);
        if (inc == -1) {
          exhausted = true;
          break;
        }
        charsRead += inc;
        if (charsRead == chars.length && charsRead < limit) {
          chars = ArrayUtil.grow(chars);
