     * {@link #size()} to obtain the size of data stored in the buffer.</p>
     *
     * @return internal byte array.
     */
    public byte[] array() {
        return data;
    }

    private void resize(int newLength) {
        int len = data.length;
        if (len <= 0) {
            len = 1;
        }
        if (newLength < NAIVE_RESIZE_LIMIT) {
