        String name = DOMUtil.getAttr(node,  CoreDescriptor.CORE_NAME, null);
        String dataDir = DOMUtil.getAttr(node,  CoreDescriptor.CORE_DATADIR, null);
        if (name != null) {
          if (! names.contains(name)) {
            names.add(name);
