public SolrCore getCore(String name) {

    name = checkDefault(name);
    // Do this in two phases since we don't want to lock access to the cores over a load.
    SolrCore core = coreMaps.getCoreFromAnyList(name);

    if (core != null) {
      core.open();
      return core;
