            final FieldVector3D<T> v1 = applyTo(vector(0, 1, 0));
            final FieldVector3D<T> v2 = applyInverseTo(vector(0, 0, 1));
            if ((v2.getY().getReal() < -0.9999999999) || (v2.getY().getReal() > 0.9999999999)) {
