        BSPTree<Sphere1D> internal = null;
        while (node.getCut() != null) {
            internal = node;
            if (((LimitAngle) node.getCut().getHyperplane()).isDirect()) {
                node = node.getMinus();
            } else {
                node = node.getPlus();
            }
        }
        return internal;
    }

