        private List<Double> limits;
        public LimitsCollector() {
            this.limits = new ArrayList<Double>();
        }
        public BSPTreeVisitor.Order visitOrder(final BSPTree<Sphere1D> node) {
            return Order.MINUS_PLUS_SUB;
