private static double sumDeltaMinusDeltaSum(final double p,
                                                final double q) {
        if (p < 10.0) {
            throw new NumberIsTooSmallException(p, 10.0, true);
        }
        if (q < 10.0) {
            throw new NumberIsTooSmallException(q, 10.0, true);
