          final DocValues d = puller.pull(r, field);
          if (d != null) {
            TypePromoter incoming = TypePromoter.create(d.getType(), d.getValueSize());
            promotedType[0] = promotedType[0].promote(incoming);
          } else if (puller.stopLoadingOnNull(r, field)){
