        public String toString(int doc) {
          return "float: [" + floatVal(doc) + "]";
        }

        @Override
        public float floatVal(int doc) {
          return (float) source.getInt(doc);
        }
      };
    default:
      throw new IOException("Type: " + type + "is not numeric");
    }

  }

  @Override
  public String description() {
    return toString();
  }

  @Override
  public int hashCode() {
    final int prime = 31;
    int result = 1;
