public class CachedSqlEntityProcessor extends SqlEntityProcessor {
  private boolean isFirst;

  @Override
  @SuppressWarnings("unchecked")
  public void init(Context context) {
    super.init(context);
    super.cacheInit();
    isFirst = true;
