    protected final TokenStream sink;
    public TokenStreamComponents(final Tokenizer source,
        final TokenStream result) {
      this.source = source;
      this.sink = result;
    }
    public TokenStreamComponents(final Tokenizer source) {
      this.source = source;
      this.sink = source;
    }
    protected void reset(final Reader reader) throws IOException {
      source.reset(reader);
    }
