      while (iter.hasNext()) {
        Map.Entry ent = (Map.Entry) iter.next();

        SegmentReader sr = (SegmentReader) ent.getValue();
        if (sr.hasChanges) {
          assert infoIsLive(sr.getSegmentInfo());
          sr.startCommit();
          boolean success = false;
          try {
            sr.doCommit(null);
            success = true;
