            return nonSingular;
        }
        public RealMatrix getInverse()
            throws InvalidMatrixException {
            if (!isNonSingular()) {
                throw new SingularMatrixException();
            }
            return solve(MatrixUtils.createRealIdentityMatrix(singularValues.length));
        }
