              && match == match(nextLevel)) {
            upTo = skipper.maxDocID(nextLevel);
            nextLevel++;
          }
        }
        switch (match) {
          case YES:
            return doc = target;
          case MAYBE:
          case IF_DOC_HAS_VALUE:
            if (target > innerApproximation.docID()) {
              target = innerApproximation.advance(target);
