    }
    this.truncateAfter = truncateAfter;
    this.useCodePoints = useCodePoints;
  }

  @Override
  public final boolean incrementToken() throws IOException {
    if (!input.incrementToken()) {
      return false;
    }
    if (keywordAttr.isKeyword()) {
      return true;
