    throws IOException {
    for (int i = 0; i < searchers.length; i++) {

      final int start = starts[i];

      searchers[i].search(query, filter, new HitCollector() {
	  public void collect(int doc, float score) {
	    results.collect(doc + start, score);
	  }
	});

    }
  }
