      } else {
        isTotal = Operations.isTotal(automaton);
      }
      if (isTotal) {
        type = AUTOMATON_TYPE.ALL;
        term = null;
        commonSuffixRef = null;
        runAutomaton = null;
        this.automaton = null;
        this.finite = null;
        sinkState = -1;
        return;
