  public FixedBitSet getBits() {
    int maxDoc = size() > 0 ? docs[size()-1] : 0;
    FixedBitSet bs = new FixedBitSet(maxDoc+1);
    for (int doc : docs) {
      bs.set(doc);
    }
    return bs;
  }
}

