  protected Character getCharacter(Map<String,String> args, String name, Character defaultVal) {
    String s = args.remove(name);
    if (s == null) {
      return defaultVal;
    } else if (s.length() == 0) {
      return null;
    } else {
      if (s.length() != 1) {
        throw new IllegalArgumentException(name + " should be a char. \"" + s + "\" is invalid");
      } else {
        return s.charAt(0);
      }
    }
  }
}

