      }
      final OneMerge merge = new OneMerge(eligible.subList(start, end));
      if (verbose(mergeContext)) {
        message("add merge=" + segString(mergeContext, merge.segments), mergeContext);
      }
      spec.add(merge);
      start = end;
    }
    return spec;
  }

