      }
      deleteQueue.clear();

      // jump over any possible in flight ops:
      deleteQueue.skipSequenceNumbers(perThreadPool.getActiveThreadStateCount()+1);

      flushControl.abortPendingFlushes();
      flushControl.waitForFlush();
      success = true;
