  private final static int MIN_PAUSE_CHECK_MSEC = 25;

  private final static long MIN_PAUSE_NS = TimeUnit.MILLISECONDS.toNanos(2);
  private final static long MAX_PAUSE_NS = TimeUnit.MILLISECONDS.toNanos(250);

