    double maxLat;
    boolean isWithin;
    do {
      maxLon = GeoPointField.decodeLongitude(currEnd);
      maxLat = GeoPointField.decodeLatitude(currEnd);

      isWithin = false;
      // within or a boundary
      if (boundary(minLat, maxLat, minLon, maxLon) == true) {
        isWithin = within(minLat, maxLat, minLon, maxLon);
