		int counter = 0;
		for (Entry<ResolvableType, String> entry : RESERVED_TYPES.entrySet()) {
			builder.add("$T $L", entry.getKey().toClass(), entry.getValue());
			if (++counter < RESERVED_TYPES.size()) {
				builder.add(", ");
			}
		}
