        } else {
          queue.updateTop();
        }
      }

      sortInfo.mergeTime += System.currentTimeMillis() - start;
      sortInfo.mergeRounds++;
    } finally {
      IOUtils.close(streams);
    }

    IOUtils.deleteFiles(trackingDir, segments);

    segments.clear();
    segments.add(newSegmentName);

    sortInfo.tempMergeFiles++;
  }

