        minLon = Integer.MIN_VALUE;
        maxLon = maxLonEncoded;
        minLat = minLatEncoded;
        maxLat = maxLatEncoded;
        // box2
        minLon2 = minLonEncoded;
        maxLon2 = Integer.MAX_VALUE;
        minLat2 = minLatEncoded;
        maxLat2 = maxLatEncoded;
      } else {
        minLon = minLonEncoded;
        maxLon = maxLonEncoded;
        minLat = minLatEncoded;
        maxLat = maxLatEncoded;
      }
    }
    setBottomCounter++;
  }

  @Override
