		var cached = isPropertyParameterCache.get(property);

		if (cached != null) {
			return cached;
		}

		var result = false;
		for (Parameter<?, P> parameter : parameters) {
			if (parameter.maps(property)) {
				result = true;
				break;
			}
		}

		isPropertyParameterCache.put(property, result);

		return result;
	}

