PropertyPath getPropertyPath(String path, TypeInformation<?> type) {
		if (!isPathVisible(path)) {
			return null;
		}
		if (pathSpecs.containsKey(path)) {
			return PropertyPath.from(toDotPath(pathSpecs.get(path).getPath()), type);
