            ? DirectedMultiNodeConnections.<N, E>of()
            : DirectedNodeConnections.<N, E>of()
        : allowsParallelEdges()
            ? UndirectedMultiNodeConnections.<N, E>of()
            : UndirectedNodeConnections.<N, E>of();
