      throw new NumberFormatException("unable to parse '"+string+"' as integer");
    }
    int length = string.length(), i = 0;
    if (length == 0) {
      throw new NumberFormatException("unable to parse '"+string+"' as integer");
    }
    boolean negative = string.charAt(i) == '-';
    if (negative && ++i == length) {
      throw new NumberFormatException("unable to parse '"+string+"' as integer");
    }

