      int digit = Character.digit(string.charAt(offset++), radix);
      if (digit == -1) {
        throw new NumberFormatException("unable to parse '"+string+"' as integer");
      }
      if (max > result) {
        throw new NumberFormatException("unable to parse '"+string+"' as integer");
