        throw new NumberFormatException("unable to parse '"+string+"' as integer");
      }
      result = next;
    }
    if (!negative) {
      result = -result;
      if (result < 0) {
        throw new NumberFormatException("unable to parse '"+string+"' as integer");
      }
    }
